198	        let range = TableRange {
199	            first: subpath.first_edge,
200	            count: subpath.edge_count,
201	        };
202	        range.require(value.edges.len(), 0)?;
203	        if range.first < end {
204	            return Err(invalid(0));
205	        }
206	        end = range.end().ok_or_else(|| invalid(0))?;
207	    }
208	    for segment in &value.segments {
209	        charge(control, WorkKind::TokenVisit)?;
210	        segment_valid(source, *segment, value.edges.len(), value.numbers.len())?;
211	    }
212	    for number in &value.numbers {
213	        charge(control, WorkKind::SourceRead)?;
214	        span(source, number.source)?;
215	        if !number.value.is_finite() {
216	            return Err(invalid(number.source.start));
217	        }
218	    }
219	    Ok(())
