241	            .shapes
242	            .checked_mul(16)
243	            .ok_or_else(crate::memory::arithmetic)?;
244	        room!(self, i, dash_values, values.len(), cap, 0);
245	        let mark = self.mark(scene)?;
246	        let first = self.scenes[i].dash_values.len();
247	        for value in values {
