   117	/// No default or fake provider is supplied; native implementation is a later gate.
   118	pub trait MediaProvider {
   119	    fn layout_text(
   120	        &mut self,
   121	        request: TextRequest<'_>,
   122	        control: &mut dyn WorkControl,
   123	    ) -> std::result::Result<TextLayout, MediaError>;
   124	    fn decode_image(
