   130	impl TextRequest<'_> {
   131	    /// Validate bounded provider input before entering a native API.
   132	    pub fn validate(&self, control: &mut dyn WorkControl) -> Result<()> {
   133	        control.checkpoint().map_err(crate::types::stopped)?;
   134	        if self.text.len() > 64 * 1024 || self.font_families.len() > 32 {
   135	            return Err(crate::types::limit(crate::LimitKind::TextBytes));
   136	        }
   137	        for byte in self.text {
   138	            let _ = byte;
   139	            control
   140	                .charge(crate::WorkKind::Media, 1)
   141	                .map_err(crate::types::stopped)?;
   142	        }
   143	        if std::str::from_utf8(self.text).is_err()
   144	            || !self.size_points.is_finite()
   145	            || self.size_points <= 0.0
   146	            || self.size_points > 4096.
   147	            || !self.weight.is_finite()
   148	            || !(100.0..=900.0).contains(&self.weight)
   149	            || !self.letter_spacing_points.is_finite()
   150	            || self.letter_spacing_points.abs() > 4096.
   151	        {
   152	            return Err(crate::types::invalid(0));
   153	        }
