270	    fn reserve_segment(&mut self) -> Result<(), ControlledError<Diagnostic>> {
271	        let offset = self.reader.base + self.group.start;
272	        let required = self.document.numbers.len().checked_add(self.group.count).ok_or(ControlledError::Overflow)?;
273	        if self.document.segments.len() >= self.max_commands || required > self.max_numbers {
274	            return Err(ControlledError::Original(failure(DiagnosticKind::Limit, offset)));
275	        }
276	        reserve(&mut self.document.segments, 1, self.max_commands, offset)?;
277	        reserve(&mut self.document.numbers, self.group.count, self.max_numbers, offset)?;
