286	        reserve(&mut self.document.subpaths, 1, MAX_PATH_EDGES, offset)?;
287	        self.document.subpaths.push(PathSubpath { first_edge: self.current_subpath_edge, edge_count, closed });
288	        Ok(())
289	    }
