291	        self.document.segments[self.group.segment_index].edge_count = self.document.edges.len()
292	            .checked_sub(self.group.first_edge).ok_or(ControlledError::Overflow)?;
293	        Ok(())
294	    }
295	    fn check_points(&self, points: &[Point]) -> Result<(), ControlledError<Diagnostic>> {
296	        if points.iter().all(|point| flatten::bounded(*point)) { Ok(()) }
297	        else { Err(ControlledError::Original(failure(DiagnosticKind::Number, self.group_offset()))) }
298	    }
299	    fn group_offset(&self) -> usize { self.reader.base + self.group.group_start }
300	    fn next_gap(&mut self) { self.had_separator = false; self.phase = Phase::Gap; }
