437	pub(crate) fn group(
438	    builder: &SceneBuilder,
439	    id: SceneId,
440	    value: &OpacityGroup,
441	    control: &mut dyn WorkControl,
442	) -> Result<()> {
443	    let scene = builder.scene(id)?;
444	    value.shapes.require(scene.shapes.len(), 0)?;
445	    if !value.opacity.is_finite() || !(0.0..=1.0).contains(&value.opacity) || value.blend_mode > 4 {
446	        return Err(invalid(0));
447	    }
448	    if let Some(filter) = value.filter {
449	        if scene.filter(filter).is_none() {
450	            return Err(invalid(0));
451	        }
452	    }
453	    if let Some(mask) = value.mask {
454	        if scene.mask(mask).is_none() {
455	            return Err(invalid(0));
456	        }
457	    }
458	    let mut parent = value.parent;
459	    let mut depth = 1;
460	    while let Some(id) = parent {
461	        charge(control, WorkKind::ClipChain)?;
462	        let group = scene.group(id).ok_or_else(|| invalid(0))?;
463	        if value.shapes.first < group.shapes.first || value.shapes.end() > group.shapes.end() {
464	            return Err(invalid(0));
465	        }
465	        }
466	        parent = group.parent;
467	        depth += 1;
468	        if depth > 64 {
469	            return Err(limit(LimitKind::Depth));
470	        }
471	    }
472	    Ok(())
473	}
474	pub(crate) fn scene(
475	    builder: &SceneBuilder,
476	    id: SceneId,
477	    control: &mut dyn WorkControl,
478	) -> Result<()> {
479	    control.checkpoint().map_err(stopped)?;
480	    let i = builder.index(id)?;
481	    let data = &builder.scenes[i];
482	    let view = builder.scene(id)?;
483	    viewport(view.viewport)?;
484	    if view.edges.len() != view.edge_colors.len() || view.edges.len() != view.edge_shape_ids.len() {
485	        return Err(invalid(0));
486	    }
487	    for (records, serials) in [
488	        (data.shapes.len(), data.shapes_serials.len()),
489	        (data.transforms.len(), data.transforms_serials.len()),
490	        (data.clips.len(), data.clips_serials.len()),
491	        (data.patterns.len(), data.patterns_serials.len()),
492	        (data.masks.len(), data.masks_serials.len()),
493	        (data.filters.len(), data.filters_serials.len()),
494	        (data.groups.len(), data.groups_serials.len()),
495	    ] {
496	        if records != serials {
497	            return Err(invalid(0));
498	        }
499	    }
500	    for (index, &e) in view.edges.iter().enumerate() {
501	        charge(control, WorkKind::Edge)?;
502	        edge(e)?;
503	        let shape = view
504	            .edge_shape(index)
505	            .and_then(|id| view.shape(id))
506	            .ok_or_else(|| invalid(0))?;
507	        if index < shape.edges.first || index >= shape.edges.end().ok_or_else(|| invalid(0))? {
508	            return Err(invalid(0));
509	        }
510	    }
511	    for shape in view.shapes {
512	        shape_attributes(builder, id, shape, control)?;
513	        shape.edges.require(view.edges.len(), 0)?;
514	        shape.subpaths.require(view.path_subpaths.len(), 0)?;
515	        let mut end = shape.edges.first;
516	        for subpath in shape
517	            .subpaths
518	            .slice(view.path_subpaths)
519	            .ok_or_else(|| invalid(0))?
520	        {
521	            charge(control, WorkKind::TokenVisit)?;
522	            let range = TableRange {
523	                first: subpath.first_edge,
524	                count: subpath.edge_count,
525	            };
526	            range.require(view.edges.len(), 0)?;
527	            if range.first < end || range.end() > shape.edges.end() {
528	                return Err(invalid(0));
529	            }
530	            end = range.end().ok_or_else(|| invalid(0))?;
531	        }
532	    }
533	    for segment in view.path_segments {
534	        charge(control, WorkKind::TokenVisit)?;
535	        segment_valid(
536	            &builder.source,
537	            segment.path,
538	            view.edges.len(),
539	            view.path_numbers.len(),
540	        )?;
541	        let shape = view.shape(segment.shape).ok_or_else(|| invalid(0))?;
542	        let range = TableRange {
543	            first: segment.path.first_edge,
544	            count: segment.path.edge_count,
545	        };
546	        if range.first < shape.edges.first || range.end() > shape.edges.end() {
547	            return Err(invalid(0));
548	        }
549	    }
550	    for number in view.path_numbers {
551	        charge(control, WorkKind::SourceRead)?;
552	        span(&builder.source, number.source)?;
553	        if !number.value.is_finite() {
554	            return Err(invalid(number.source.start));
555	        }
556	    }
557	    for (index, value) in view.transforms.iter().enumerate() {
558	        transform(builder, id, value, control)?;
559	        if value.parent.is_some_and(|p| p.index() >= index) {
560	            return Err(invalid(value.source_offset));
561	        }
562	    }
563	    let mut pixels = 0usize;
564	    for value in view.images {
565	        image(value, control)?;
566	        pixels = crate::memory::add(
567	            pixels,
568	            (value.pixels.width as usize) * (value.pixels.height as usize),
569	        )?;
570	        if pixels > 67_108_864 {
571	            return Err(limit(LimitKind::Images));
572	        }
573	    }
574	    if pixels != data.image_pixels {
575	        return Err(invalid(0));
576	    }
577	    for (index, value) in view.clips.iter().enumerate() {
578	        clip(builder, id, value, control)?;
579	        if value.parent.is_some_and(|p| p.index() >= index) {
580	            return Err(invalid(0));
581	        }
582	    }
583	    for value in view.patterns {
584	        pattern(builder, id, value, control)?;
585	    }
586	    for value in view.masks {
587	        mask(builder, id, value, control)?;
588	    }
589	    for value in view.fill_paints.iter().chain(view.stroke_paints) {
590	        paint(builder, id, value, control)?;
591	    }
592	    for value in view.filters {
593	        charge(control, WorkKind::FilterPixel)?;
594	        value.primitives.require(view.filter_primitives.len(), 0)?;
595	        let primitives = value
596	            .primitives
597	            .slice(view.filter_primitives)
598	            .ok_or_else(|| invalid(0))?;
599	        filter(*value, primitives, control)?;
600	        for primitive in primitives {
601	            charge(control, WorkKind::SourceRead)?;
602	            source_offset(&builder.source, primitive.source_offset)?;
603	        }
604	    }
605	    for (index, value) in view.groups.iter().enumerate() {
606	        group(builder, id, value, control)?;
607	        if value.parent.is_some_and(|p| p.index() >= index) {
608	            return Err(invalid(0));
609	        }
610	    }
611	    for value in view.dash_values {
612	        charge(control, WorkKind::StrokeTest)?;
613	        if !coord(*value) || *value < 0.0 {
614	            return Err(invalid(0));
615	        }
616	    }
617	    // Unreferenced stops and primitives are still retained user input and must validate.
618	    for value in view.stops {
619	        charge(control, WorkKind::PaintVisit)?;
620	        if !value.offset.is_finite() || !(0.0..=1.0).contains(&value.offset) {
621	            return Err(invalid(0));
622	        }
623	    }
624	    Ok(())
625	}

